mapper.select:
SELECT p.name
FROM product p
JOIN (
    SELECT product_id, MAX(created_at) AS last_view
    FROM user_behavior
    WHERE user_id = #{userId}
      AND event_type = 'VIEW'
      AND created_at >= #{since}
    GROUP BY product_id
    ORDER BY last_view DESC
    LIMIT #{limit}
) recent ON recent.product_id = p.id
ORDER BY recent.last_view DESC

SELECT id FROM product WHERE status = 'ON_SALE' AND deleted_at IS NULL AND category_id IN
#{categoryId}
ORDER BY id DESC LIMIT #{limit}
